#!/usr/bin/env bash
set -euo pipefail
blocked_worker='gnk-asg-news-backend';base='https://gnk-asg.hr';workdir="${1:-deploy-preflight}";mkdir -p "$workdir"
known_recovery_fix_present(){ local v17='workers/gnk-asg-direct-operator/src/index-unified-auth-v17.js' v19='workers/gnk-asg-direct-operator/src/index-unified-auth-v19.js' expected_v17='f113c5b77ff2572e1723274a86b687904e9b99f8' expected_v19='f7a20819b51d2ef515d719b82b759b2ee1883a7e';[[ -f "$v17" && -f "$v19" ]]||return 1;[[ "$(git hash-object "$v17")" = "$expected_v17" ]]||return 1;[[ "$(git hash-object "$v19")" = "$expected_v19" ]]||return 1;}
check_route(){ local path="$1" name="$2" status body="$workdir/${2}.body" headers="$workdir/${2}.headers";status=$(curl --silent --show-error --location --dump-header "$headers" --output "$body" --write-out '%{http_code}' "${base}${path}?route-readiness=$(date +%s)"||true);echo "PREFLIGHT ${path} -> HTTP ${status}";if grep -Fiq "$blocked_worker" "$headers"||grep -Fq "$blocked_worker" "$body";then echo "Deploy blocked: ${path} is still owned by ${blocked_worker}." >&2;grep -Ei '^(server|cf-ray|cf-cache-status|x-gnk-|location|content-type):' "$headers" >&2||true;head -c 800 "$body" >&2||true;echo >&2;return 1;fi;if [[ "$status" = "200" ]];then return 0;fi;if [[ "$status" = "500" ]]&&grep -Eiq '^server: cloudflare' "$headers"&&grep -Eiq '^content-type: text/plain' "$headers"&&grep -Fiq 'error code: 1101' "$body"&&known_recovery_fix_present;then echo "RECOVERY PREFLIGHT ${path}: allowing the audited recovery because the approved source contains canonical asset paths, hard-stop newsroom fallback and the V29 direct-index unified release.";return 0;fi;echo "Deploy blocked: ${path} is not healthy before deploy." >&2;grep -Ei '^(server|cf-ray|cf-cache-status|x-gnk-|location|content-type):' "$headers" >&2||true;head -c 800 "$body" >&2||true;echo >&2;return 1;}
check_route '/newsroom/' 'newsroom-hr';check_route '/en/newsroom/' 'newsroom-en';echo 'Newsroom route readiness passed. No production changes were made.'